prose:
:where(h1, h2, h3, h4, h5, h6) {
  font-family: var(--font-family-heading);
  color: var(--color-text-primary);
}

:where(p) {
  font-family: var(--font-family-body);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-normal);
  line-height: 1.4286;
